import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Languages as First-Class Values","description":"","frontmatter":{"title":"Languages as First-Class Values","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"proposed","status_note":"Proposed — `Language` and `eval` are handl values/functions."},"headers":[],"relativePath":"handl/project/adrs/0041-languages-as-first-class-values.md","filePath":"vendored/handl/project/adrs/0041-languages-as-first-class-values.md"}'),a={name:`handl/project/adrs/0041-languages-as-first-class-values.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0041-languages-as-first-class-values" tabindex="-1">ADR-0041: Languages as First-Class Values <a class="header-anchor" href="#adr-0041-languages-as-first-class-values" aria-label="Permalink to “ADR-0041: Languages as First-Class Values”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>Language</code> is a handl-level type</strong> — a language definition is a value the program can hold, pass and inspect.</li><li><strong><code>eval</code> is a handl function</strong> — evaluating an AST is a function call, not a privileged host operation.</li><li><strong><code>self</code> is the running language</strong>, handed to the program, so a program can evaluate in its own language.</li><li><strong>Language combinators are handl functions</strong> — composing languages is ordinary composition.</li><li><strong>The bootstrap is a compilation step, not interpretation</strong> — the initial language is compiled, then evaluated as data.</li><li><strong>Structured by default; <code>vau</code> is a typed escape</strong> for the cases structure cannot express.</li><li><strong>Capability discipline at the language level</strong> — a language declares what it may do; the host enforces it.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><code>Language</code> and <code>eval</code> lived in Rust, so a program could not inspect or extend its own language and <code>self</code> was a host notion. Values and functions make self-hosting ordinary handl, and capability discipline keeps it safe.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep <code>Language</code>/<code>eval</code> host-only</strong> — self-hosting would stay impossible.</li><li><strong>Interpret the bootstrap</strong> — it is compiled once, then data.</li><li><strong>Untyped <code>vau</code></strong> — the escape is typed so capability discipline holds.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Languages are data; combinators are handl functions.</li><li><code>self</code> becomes an ambient value, not a host flag.</li><li><code>vau</code> is the only escape hatch and is typed.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — <code>Language</code> value, <code>eval</code> function, <code>self</code>.</li><li><code>crates/handl-kit-data-canonical/</code> — the language data.</li><li>Self-hosting tests (<code>handl-defining-handl</code> / dogfood gate).</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The seven decisions in full, the bootstrap, <code>vau</code> and the capability model: +<a href="./../design/0041-languages-as-first-class-values.html"><code>design/0041-languages-as-first-class-values.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};